[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SnapFrame — Capture, Create & Share What You Love</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --black: #000000;
  --purple: #7638FA;
  --orange: #FF7A00;
  --purple-light: #ede4ff;
  --orange-light: #fff3e6;
  --gray-50: #fafafa;
  --gray-100: #f5f5f5;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--black);
  background: #fff;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font: inherit; border: none; background: none; }
ul { list-style: none; }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ─── Header ─── */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, var(--purple), var(--orange));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a { font-size: 0.938rem; font-weight: 500; color: var(--gray-700); transition: color 0.2s; }
.nav-links a:hover { color: var(--black); }

.btn-login {
  padding: 8px 20px;
  background: var(--black);
  color: #fff !important;
  border-radius: var(--radius-full);
  font-weight: 600 !important;
  font-size: 0.875rem !important;
  transition: opacity 0.2s;
}
.btn-login:hover { opacity: 0.85; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  padding: 4px 0;
  z-index: 101;
}
.hamburger span {
  display: block;
  height: 2.5px;
  background: var(--black);
  border-radius: 2px;
  transition: all 0.3s ease;
  transform-origin: center;
}
.hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  background: #fff;
  z-index: 99;
  padding: 96px 24px 40px;
  flex-direction: column;
  gap: 8px;
}
.mobile-nav.active { display: flex; }
.mobile-nav a {
  font-size: 1.25rem;
  font-weight: 600;
  padding: 12px 0;
  border-bottom: 1px solid var(--gray-100);
  color: var(--gray-800);
}
.mobile-nav .btn-login {
  display: inline-block;
  text-align: center;
  margin-top: 16px;
  padding: 14px 32px;
  font-size: 1rem !important;
}

/* ─── Hero ─── */
.hero {
  padding: 100px 0 120px;
  position: relative;
  overflow: hidden;
  background: linear-gradient(180deg, #faf8ff 0%, #fff6f0 50%, #fff 100%);
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(118,56,250,0.08) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(255,122,0,0.07) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 780px;
}

.hero h1 {
  font-size: clamp(2.5rem, 5.5vw, 4.5rem);
  font-weight: 900;
  line-height: 1.08;
  letter-spacing: -0.03em;
  margin-bottom: 24px;
}

.hero h1 .gradient-text {
  background: linear-gradient(135deg, var(--purple) 0%, #d44aff 40%, var(--orange) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: clamp(1.063rem, 1.5vw, 1.313rem);
  color: var(--gray-600);
  line-height: 1.6;
  max-width: 580px;
  margin-bottom: 36px;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 16px 36px;
  background: var(--black);
  color: #fff;
  font-size: 1rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  transition: transform 0.2s, box-shadow 0.2s;
}
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(0,0,0,0.15); }
.btn-primary .arrow { transition: transform 0.2s; }
.btn-primary:hover .arrow { transform: translateX(3px); }

/* ─── Section titles ─── */
.section {
  padding: 100px 0;
}

.section-label {
  font-size: 0.813rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--purple);
  margin-bottom: 12px;
}

.section-heading {
  font-size: clamp(1.75rem, 3.5vw, 2.75rem);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 20px;
}

.section-description {
  font-size: 1.125rem;
  color: var(--gray-600);
  line-height: 1.7;
  max-width: 640px;
  margin-bottom: 32px;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 1rem;
  font-weight: 700;
  color: var(--purple);
  transition: gap 0.2s;
}
.text-link:hover { gap: 10px; }
.text-link .arrow { font-size: 1.1em; transition: transform 0.2s; }
.text-link:hover .arrow { transform: translateX(3px); }

/* ─── Features ─── */
.features {
  background: #fff;
}

.feature-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-top: 48px;
}

.feature-card {
  padding: 32px 28px;
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
  transition: transform 0.2s, box-shadow 0.2s;
}
.feature-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.06); }

.feature-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 16px;
}

.feature-icon.clips { background: var(--purple-light); color: var(--purple); }
.feature-icon.stories { background: var(--orange-light); color: var(--orange); }
.feature-icon.dms { background: #e8f5e9; color: #2e7d32; }
.feature-icon.explore { background: #e3f2fd; color: #1565c0; }

.feature-card h3 { font-size: 1.063rem; font-weight: 700; margin-bottom: 8px; }
.feature-card p { font-size: 0.875rem; color: var(--gray-500); line-height: 1.6; }

/* ─── Safety ─── */
.safety {
  background: linear-gradient(180deg, #faf8ff 0%, #fff 100%);
  border-top: 1px solid var(--gray-100);
  border-bottom: 1px solid var(--gray-100);
}

.safety-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
  margin-top: 40px;
}

.safety-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.safety-badge {
  padding: 24px;
  background: #fff;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
  text-align: center;
  transition: transform 0.2s;
}
.safety-badge:hover { transform: scale(1.03); }

.safety-badge .icon {
  font-size: 2rem;
  margin-bottom: 8px;
}

.safety-badge h4 { font-size: 0.875rem; font-weight: 700; }
.safety-badge p { font-size: 0.781rem; color: var(--gray-500); margin-top: 4px; }

/* ─── Creators ─── */
.creators {
  background: #fff;
}

.creator-showcase {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 24px;
  margin-top: 48px;
}

.creator-card {
  border-radius: var(--radius-xl);
  overflow: hidden;
  position: relative;
  aspect-ratio: 3/4;
  background: var(--gray-100);
}

.creator-card .card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: linear-gradient(135deg, #e8ddff 0%, #ffdcc4 50%, #c4e0ff 100%);
}

.creator-card .card-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 32px 24px;
  background: linear-gradient(transparent, rgba(0,0,0,0.75));
  color: #fff;
}

.creator-card .card-overlay h3 {
  font-size: 1.25rem;
  font-weight: 800;
  margin-bottom: 4px;
}

.creator-card .card-overlay span {
  font-size: 0.813rem;
  opacity: 0.85;
}

/* ─── Tagline Banner ─── */
.tagline-banner {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--purple) 0%, #9b5fff 50%, var(--orange) 100%);
  text-align: center;
}

.tagline-banner h2 {
  font-size: clamp(1.75rem, 4vw, 3rem);
  font-weight: 900;
  color: #fff;
  letter-spacing: -0.02em;
}

/* ─── News ─── */
.news {
  background: #fff;
  padding-bottom: 80px;
}

.news-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 40px;
  flex-wrap: wrap;
  gap: 16px;
}

.news-controls {
  display: flex;
  gap: 8px;
}

.news-arrow {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1.5px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: var(--gray-700);
  transition: all 0.2s;
  background: #fff;
}
.news-arrow:hover { border-color: var(--black); color: var(--black); }

.news-carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 8px;
}
.news-carousel::-webkit-scrollbar { display: none; }

.news-card {
  flex: 0 0 340px;
  scroll-snap-align: start;
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
}
.news-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.06); }

.news-card-thumb {
  width: 100%;
  height: 200px;
  background: linear-gradient(135deg, var(--purple-light), var(--orange-light));
  position: relative;
  overflow: hidden;
}

.news-card-thumb .thumb-accent {
  position: absolute;
  border-radius: 50%;
  opacity: 0.15;
}
.news-card-thumb .thumb-accent.a1 {
  width: 140px; height: 140px;
  background: var(--purple);
  top: -30px; right: -30px;
}
.news-card-thumb .thumb-accent.a2 {
  width: 100px; height: 100px;
  background: var(--orange);
  bottom: -20px; left: -20px;
}

.news-card-body { padding: 20px; }

.news-tags {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}

.news-tag {
  font-size: 0.688rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  background: var(--purple-light);
  color: var(--purple);
}

.news-tag.orange { background: var(--orange-light); color: var(--orange); }

.news-card h3 {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 8px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.news-date {
  font-size: 0.813rem;
  color: var(--gray-500);
}

/* ─── CTA Download ─── */
.cta-download {
  padding: 100px 0;
  background: var(--gray-50);
  text-align: center;
}

.cta-download h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 900;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.cta-download p {
  font-size: 1.125rem;
  color: var(--gray-600);
  margin-bottom: 36px;
}

.download-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn-store {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 28px;
  background: var(--black);
  color: #fff;
  border-radius: var(--radius-md);
  font-weight: 700;
  font-size: 0.938rem;
  transition: opacity 0.2s, transform 0.2s;
}
.btn-store:hover { opacity: 0.9; transform: translateY(-2px); }
.btn-store svg { width: 24px; height: 24px; fill: #fff; }

/* ─── Footer ─── */
.footer {
  background: var(--gray-900);
  color: #fff;
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--gray-400);
  margin-bottom: 16px;
}

.footer-col ul { display: flex; flex-direction: column; gap: 10px; }

.footer-col a {
  font-size: 0.875rem;
  color: var(--gray-300);
  transition: color 0.2s;
}
.footer-col a:hover { color: #fff; }

.footer-external { display: inline-flex; align-items: center; gap: 3px; }
.footer-external .ext-icon { font-size: 0.75rem; opacity: 0.6; }

.footer-bottom {
